#!/usr/bin/env node
/**
 * build/build.mjs — renders the static gallery site into dist/.
 *
 * Inputs:
 *   src/config.json               gallery configuration (see README)
 *   src/photos/<collection.dir>/  web-sized preview images (committed)
 *   site/                         HTML/CSS/JS shell copied into dist/
 *   build/release-assets.json     filename → full-res download URL map,
 *                                 generated by build/releases.mjs in CI
 *                                 (optional; downloads simply stay hidden
 *                                 when it is missing)
 *
 * Outputs:
 *   dist/index.html, gallery.json, gate.json, styles.css, app.js,
 *   robots.txt, .nojekyll, favicon.svg, photos/<dir>/*
 *
 * Zero npm dependencies — plain Node >= 20.
 */
import { cp, mkdir, readdir, readFile, rm, stat, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const CONFIG_PATH = process.env.CONFIG || path.join(ROOT, "src", "config.json");
const ASSETS_PATH = process.env.RELEASE_ASSETS || path.join(ROOT, "build", "release-assets.json");
const OUT = process.env.OUT_DIR || path.join(ROOT, "dist");
const SITE_DIR = path.join(ROOT, "site");
const PHOTOS_DIR = path.join(ROOT, "src", "photos");

const IMAGE_EXTENSIONS = new Set([".jpg", ".jpeg", ".png", ".webp", ".avif", ".gif", ".svg"]);
const naturalSort = new Intl.Collator(undefined, { numeric: true, sensitivity: "base" });
const warn = (...args) => console.warn("[build] warn:", ...args);

function fail(message) {
  console.error(`[build] error: ${message}`);
  process.exit(1);
}

async function readJson(file, fallback) {
  if (!existsSync(file)) {
    if (fallback === undefined) fail(`missing file: ${file}`);
    return fallback;
  }
  try {
    return JSON.parse(await readFile(file, "utf8"));
  } catch (err) {
    fail(`${file} is not valid JSON: ${err.message}`);
  }
}

/** Match a preview filename to a release asset download URL. */
function findDownload(assets, dir, file) {
  if (!assets || typeof assets !== "object") return null;
  const base = path.parse(file).name.toLowerCase();
  const ext = path.parse(file).ext.toLowerCase();
  const candidates = [`${base}${ext}`, base, `${base}.jpg`, `${base}.jpeg`];
  for (const key of candidates) {
    const hit = assets[key.toLowerCase()];
    if (typeof hit === "string") return hit;
  }
  return null;
}

async function listCollectionPhotos(dir) {
  const abs = path.join(PHOTOS_DIR, dir);
  if (!existsSync(abs)) return [];
  const entries = await readdir(abs, { withFileTypes: true });
  return entries
    .filter((e) => e.isFile() && IMAGE_EXTENSIONS.has(path.extname(e.name).toLowerCase()))
    .map((e) => e.name)
    .sort(naturalSort.compare);
}

async function dirSize(dir) {
  let total = 0;
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const abs = path.join(dir, entry.name);
    total += entry.isDirectory() ? await dirSize(abs) : (await stat(abs)).size;
  }
  return total;
}

const mb = (bytes) => `${(bytes / 1024 / 1024).toFixed(1)} MB`;

async function main() {
  const config = await readJson(CONFIG_PATH);
  const releaseIndex = await readJson(ASSETS_PATH, {});

  // ---- validate config -------------------------------------------------
  if (!config.studio?.name) fail("config.studio.name is required");
  if (!config.client?.name) fail("config.client.name is required");
  if (!Array.isArray(config.collections) || config.collections.length === 0)
    fail("config.collections must list at least one collection");

  const ids = new Set();
  for (const coll of config.collections) {
    if (!coll.id || !coll.dir) fail(`collection "${coll.id ?? "?"}": id and dir are required`);
    if (ids.has(coll.id)) fail(`duplicate collection id: ${coll.id}`);
    ids.add(coll.id);
  }
  if (config.gate?.enabled && !config.gate.codeHash)
    warn("gate.enabled is true but gate.codeHash is empty — the page will show a setup error.");

  // ---- clean output ----------------------------------------------------
  await rm(OUT, { recursive: true, force: true });
  await mkdir(OUT, { recursive: true });

  // ---- copy static shell -----------------------------------------------
  await cp(SITE_DIR, OUT, { recursive: true });

  // build the gallery manifest (previews are copied above)
  const collections = [];
  let photoCount = 0;
  for (const coll of config.collections) {
    const files = await listCollectionPhotos(coll.dir);
    if (files.length === 0) warn(`collection "${coll.id}" has no photos in src/photos/${coll.dir}/`);

    // copy this collection's previews into dist/photos/<dir>/
    await mkdir(path.join(OUT, "photos", coll.dir), { recursive: true });
    await Promise.all(
      files.map((f) => cp(path.join(PHOTOS_DIR, coll.dir, f), path.join(OUT, "photos", coll.dir, f)))
    );

    const assetsForDir = releaseIndex[coll.dir] ?? {};
    const photos = files.map((file) => ({
      file,
      url: `photos/${coll.dir}/${encodeURIComponent(file)}`,
      download: findDownload(assetsForDir, coll.dir, file),
    }));
    photoCount += photos.length;

    // Collection-level ZIP download (if the release carries one).
    const zips = Object.entries(assetsForDir).filter(([name]) => name.endsWith(".zip"));
    let zipUrl = null;
    if (coll.zipAsset) {
      zipUrl = assetsForDir[coll.zipAsset.toLowerCase()] ?? null;
      if (!zipUrl) warn(`collection "${coll.id}": zip asset "${coll.zipAsset}" not found in release`);
    } else if (zips.length === 1) {
      zipUrl = zips[0][1];
    }

    collections.push({
      id: coll.id,
      title: coll.title || coll.id,
      description: coll.description || "",
      date: coll.date || "",
      photos,
      zipUrl,
    });
  }

  const withDownloads = collections.reduce(
    (n, c) => n + c.photos.filter((p) => p.download).length,
    0
  );
  if (photoCount > 0 && withDownloads === 0)
    warn("no per-photo download links matched — upload originals to a Release (see README: Delivering photos).");

  // ---- write manifest + gate --------------------------------------------
  await writeFile(
    path.join(OUT, "gallery.json"),
    JSON.stringify({ studio: config.studio, client: config.client, collections })
  );
  await writeFile(
    path.join(OUT, "gate.json"),
    JSON.stringify({
      enabled: Boolean(config.gate?.enabled),
      codeHash: config.gate?.codeHash || "",
      hint: config.gate?.hint || "",
      studio: config.studio.name,
      client: config.client.name,
    })
  );

  // ---- render index shell -------------------------------------------------
  const template = await readFile(path.join(OUT, "index.html"), "utf8");
  const title = `${config.client.name} — photo gallery`;
  await writeFile(
    path.join(OUT, "index.html"),
    template.replaceAll("{{TITLE}}", escapeHtml(title)).replaceAll("{{STUDIO}}", escapeHtml(config.studio.name))
  );

  await writeFile(path.join(OUT, "robots.txt"), "User-agent: *\nDisallow: /\n");
  await writeFile(path.join(OUT, ".nojekyll"), "");

  // ---- summary --------------------------------------------------------------
  const size = await dirSize(OUT);
  console.log(
    `[build] ok: ${collections.length} collection(s), ${photoCount} photo(s), ` +
      `${withDownloads} full-res link(s) → ${path.relative(ROOT, OUT)} (${mb(size)}, Pages soft limit 1 GB)`
  );
}

function escapeHtml(s) {
  return String(s).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
}

main().catch((err) => {
  console.error("[build] failed:", err);
  process.exit(1);
});
